          "body": "社会学家尼克拉斯·卢曼（Niklas Luhmann）认为，信任是简化复杂性的机制。在食品领域，家长由于专业知识有限，必须依赖对生产者、监管者和学校的信任。预制菜进校园打破了这种信任链条：家长无法亲眼看到制作过程，信息不对称加剧，导致不信任感被放大。当信任缺失时，任何效率上的好处都会被质疑，因为安全与健康成为不可妥协的底线。",
