      "essayQuote": "ESG报告从自愿走向强制，标志着企业社会责任从道德呼吁升格为制度约束。这背后是对外部性的矫正——企业的经营活动常产生环境污染、社会不公等负外部性，而市场机制无法自动纠正。新制度主义视角下，强制披露不仅是监管升级，更是制度环境的变迁，它重塑了企业的行为逻辑，使可持续性成为合法性的来源。当ESG成为“必答题”，企业便不能仅以利润最大化为目标，而需兼顾环境与社会效益。这一变革虽会增加短期成本，却有助于长期价值的创造。它提醒我们，资本逻辑需要被制度驯化，唯有将社会责任内化为企业基因，才能实现经济与社会的共赢。",
