          "lens": "货币政策",
          "lensId": "econ_monetary_policy",
          "body": "<b>货币政策</b>的传导逻辑是：贷款利率下行后，银行净息差被压薄，只能同步压降存款成本。2026年一季度商业银行净息差已降至约1.40%的历史新低，降息本质上是贷款端降价向存款端的滞后传导，而非银行“针对”储户。",
