      "gist": "8月5日，“泰航拒绝20多名中国乘客登机”冲上热搜第一。泰国素万那普机场8月4日晚发布声明，就执勤安保人员被拍到对中国乘客做出疑似歧视的“拉眼角”手势致歉并惩处涉事人员。事件源于7月29日多名粉丝尾随搭乘TG674航班的中国艺人不法进入休息室与登机廊桥，航司综合安全评估后拒绝22名粉丝登机，其中12人同意卸行李、10人拒绝并发生冲突。",
