            "url": "https://doi.org/10.1515/omgc-2024-0063",
            "summary": "这项研究以抖音用户为对象证明：当用户感知平台的限制越具侵入性、自由受威胁感越强，心理抗拒（reactance）就越强，反而越不配合干预。它恰好解释了“越禁越火”的逆向传播——压制非但没有消解玩梗，反而激发了用户的逆反与参与。",
