          "lensId": "econ_macro",
          "body": "<b>宏观经济学</b>看的是资金在全社会的时间配置。居民手握的存款，是银行放贷支持实体经济的源头；当银行“缺负债”、净息差承压，便会调整存款品种与利率，间接影响每个人的理财与房贷成本。宏观政策的一丝摆动，最终落在你存单的利率上。",
