          "body": "<b>社会分层</b>研究提醒我们，一个人的起跑线深受家庭阶层影响：文化资本、经济资本、社会关系往往代际传递。邹品芝用十八年体力托举换来的，是女儿与“先天优势家庭”同场竞技的入场券——这恰恰说明，阶层流动真实存在，却也异常艰难，需要个人与制度共同接力。",
